def ins(p, after, step, cls):
    s=open(p).read()
    old=f"{after}:\n" 
    i=s.index(old); j=s.index("  next: respond", i)
    s=s[:j]+f"  next: audit\n"+s[j+len("  next: respond\n"):]
    k=s.index("respond:\n")
    s=s[:k]+f"audit:\n  class: net.officefloor.hq.app.{cls}\n  govern: [ transaction ]\n  next: respond\n"+s[k:]
    open(p,'w').write(s)
